import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/** The people table's extra column headers: each contributes one or more `<th>`. */
export const PeopleColumns = defineSlot('people.columns');

/**
 * The people table's extra cells for one person's row, in the same order as PeopleColumns: each
 * contributes `<td>`s. Everything inside a person's row belongs to `person-row-<id>`.
 */
export const PersonCells = defineSlot<{ person: Person }>('people.cells');
import { useQueryClient } from '@tanstack/react-query';
import { figureToday } from '../../api/http';
import { HomeMain } from '../../slots/defs/homeMain';
import { sheetQueryKey, useCurrentSheet, useCurrentUser, type SheetInfo } from '../session/session';
import { gradeOn, peoplePath, peopleQueryKey, type Person } from '../people/people';
import { csvValue, readFresh, sheetInfoPath } from '../people/export.slot';
import { chargedOf, ratesPath, ratesQueryKey, type Rate } from '../rates/rates';
import { periodOn, periodsPath, periodsQueryKey, type Period } from '../periods/periods';
import { settingsPath, settingsQueryKey, type Settings } from '../roles/roles';
import { claimsPath, claimsQueryKey, dueByOf, type Claim } from './claims';

// The claims export button: downloads every claim on the sheet as CSV — people in list order (retired people
// included, shown or not), each person's claims oldest first — with person, number, date, amount, due, status and
// period as the claim's row shows them. Quoting and line ends as the people export. Its inputs are re-read from the
// store when pressed, as the people export's, so in an as-of view it has the claims and figures as of that date,
// and while a preview date is set its dues are the preview's.
function ExportClaims() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const queryClient = useQueryClient();
  if (!user || !sheet) return null;
  const download = async () => {
    const [info, people, claims, rates, periods, settings] = await Promise.all([
      readFresh<SheetInfo>(queryClient, sheetQueryKey(sheet), sheetInfoPath(sheet)),
      readFresh<Person[]>(queryClient, peopleQueryKey(sheet), peoplePath(sheet)),
      readFresh<Claim[]>(queryClient, claimsQueryKey(sheet), claimsPath(sheet)),
      readFresh<Rate[]>(queryClient, ratesQueryKey(sheet), ratesPath(sheet)),
      readFresh<Period[]>(queryClient, periodsQueryKey(sheet), periodsPath(sheet)),
      readFresh<Settings>(queryClient, settingsQueryKey(sheet), settingsPath(sheet)),
    ]);
    const today = figureToday(info.today);
    const lines = [['person', 'number', 'date', 'amount', 'due', 'status', 'period']];
    for (const p of people) {
      // The sheet's claims come newest first.
      const mine = claims.filter((c) => c.personId === p.id).reverse();
      for (const c of mine) {
        lines.push([p.name, c.number ?? '', c.date, c.amount,
          chargedOf(c, rates, gradeOn(p, c.date), settings, today), c.status,
          periodOn(periods, dueByOf(c))?.name ?? '']);
      }
    }
    const csv = lines.map((l) => l.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `claims-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  return (
    <button type="button" data-testid="export-claims" onClick={() => { void download(); }}>
      Export claims (CSV)
    </button>
  );
}

export const contribution = HomeMain.fill({ order: 19.1, Component: ExportClaims });
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useSheetToday } from '../session/session';
import { type Person } from '../people/people';
import { useSettings } from '../roles/roles';
import { gradeOn } from '../people/people';
import { chargedOf, sumDue, useRates } from '../rates/rates';
import { overdueOf } from './overdue.slot';
import { countsLive, holdsOf, useClaims } from './claims';

// A person's score: the dues of their counted SETTLED claims that correct nothing, divided by 100, minus 5 for each counted overdue claim, rounded half to even
// to a whole number. Worked in hundredths of the score so the rounding is exact.
export function scoreOf(settledTotal: string, overdueCount: number): string {
  const [whole, frac = '00'] = settledTotal.replace('-', '').split('.');
  const cents = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
  // the score in ten-thousandths: cents / 10000 is the settled-total / 100
  const n = (settledTotal.startsWith('-') ? -cents : cents) - 50000n * BigInt(overdueCount);
  const negative = n < 0n;
  const m = negative ? -n : n;
  let q = m / 10000n;
  const r = m % 10000n;
  if (r > 5000n || (r === 5000n && q % 2n === 1n)) q += 1n;
  return `${negative && q !== 0n ? '-' : ''}${q}`;
}

// A person's band by the score thresholds: HIGH at or above the high one, MID at or above the mid one, else LOW;
// "" while either is blank.
export function bandOf(score: string, mid: string, high: string): string {
  if (mid === '' || high === '') return '';
  const n = BigInt(score);
  if (n >= BigInt(high)) return 'HIGH';
  if (n >= BigInt(mid)) return 'MID';
  return 'LOW';
}

function ScoreHeader() {
  return (
    <>
      <th>Score</th>
      <th>Band</th>
    </>
  );
}

function PersonScore({ person }: { person: Person }) {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  const all = claims.data ?? [];
  // corrections are left out of the score's settled figures
  const settled = sumDue(all
    .filter((c) => c.personId === person.id && c.corrects === null && c.status === 'SETTLED'
      && countsLive(c, holdsOf([person]), today))
    .map((c) => chargedOf(c, rates.data, gradeOn(person, c.date), settings.data, today)));
  const { count } = overdueOf(person, all, rates.data, today, settings.data);
  const score = scoreOf(settled, count);
  return (
    <>
      <td data-testid="person-score">{score}</td>
      <td data-testid="person-band">{bandOf(score, settings.data?.scoreMid ?? '', settings.data?.scoreHigh ?? '')}</td>
    </>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 16.5, Component: ScoreHeader }),
  PersonCells.fill({ order: 16.5, Component: PersonScore }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { useRowAction } from '../../api/rowAction';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { peoplePath, peopleQueryKey, type Person } from './people';
import { useColumnShown } from './columns';

// A person's aliases — other names they go by, sorted ignoring case (the server sorts them) — and the entry and
// button that add another. An alias must not equal, ignoring case, any name or alias on the sheet or on another
// sheet of its tree (its ancestors and descendants).
function AliasesHeader() {
  return <th>Aliases</th>;
}

function PersonAliases({ person }: { person: Person }) {
  const shown = useColumnShown('aliases');
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [alias, setAlias] = useState('');
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: (body: { alias: string }) =>
      postJson<Person>(`${peoplePath(sheet ?? '')}/${person.id}/aliases`, body, user),
    onSuccess: () => {
      setAlias('');
      return queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet ?? '') });
    },
  });
  const submit = useSubmitOnce(add);
  const rowAction = useRowAction(`person-${person.id}`);
  return (
    <td>
      {shown && <><span data-testid="person-aliases">{(person.aliases ?? []).join(', ')}</span>{' '}</>}
      <input
        data-testid="person-alias-input"
        placeholder="Alias"
        value={alias}
        onChange={(e) => { setAlias(e.target.value); add.reset(); }}
      />
      <button
        type="button"
        data-testid="person-alias-add"
        disabled={add.isPending}
        onClick={() => { rowAction.take(); submit({ alias }); }}
      >
        Add alias
      </button>
      {add.isError && rowAction.isLatest && (
        <span data-testid="person-error">The alias must not be blank, nor any name or alias on the sheet.</span>
      )}
    </td>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 6.5, Component: AliasesHeader }),
  PersonCells.fill({ order: 6.5, Component: PersonAliases }),
];

